urlset:
{# Jede Seite in jeder ihrer Sprachen. Alternates nur bei Seiten mit mehr als
   einer Sprache, x-default nur, wenn es die Seite in der x-default-Sprache
   gibt. #}
{% for e in entries %}
{% for code, loc in e.urls.items() %}

    {{ loc }}
    {{ e.page.lastmod }}
    {{ e.page.priority }}
{% if e.alternates %}
{% for alt, href in e.urls.items() %}

{% endfor %}
{% if e.x_default %}

{% endif %}
{% endif %}

{% endfor %}
{% endfor %}
